package com.runtimeheal.backend.llm.model;

import java.time.Instant;

/**
 * Structured diagnostic report generated by the LLM diagnostic engine for a captured runtime incident.
 */
public class LlmDiagnosticReport {

    private String incidentId;
    private Instant timestamp;
    private String rootCause;
    private String explanation;
    private DiagnosisSeverity severity;
    private double confidenceScore;
    private RecoveryStrategy suggestedRecoveryStrategy;
    private String reasonForSuggestion;
    private String source;
    private long latencyMillis;
    private String rawModelResponse;

    public LlmDiagnosticReport() {
        this.timestamp = Instant.now();
    }

    public LlmDiagnosticReport(String incidentId, String rootCause, String explanation,
                               DiagnosisSeverity severity, double confidenceScore,
                               RecoveryStrategy suggestedRecoveryStrategy, String reasonForSuggestion,
                               String source, long latencyMillis, String rawModelResponse) {
        this.incidentId = incidentId;
        this.timestamp = Instant.now();
        this.rootCause = rootCause;
        this.explanation = explanation;
        this.severity = severity;
        this.confidenceScore = confidenceScore;
        this.suggestedRecoveryStrategy = suggestedRecoveryStrategy;
        this.reasonForSuggestion = reasonForSuggestion;
        this.source = source;
        this.latencyMillis = latencyMillis;
        this.rawModelResponse = rawModelResponse;
    }

    public String getIncidentId() {
        return incidentId;
    }

    public void setIncidentId(String incidentId) {
        this.incidentId = incidentId;
    }

    public Instant getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(Instant timestamp) {
        this.timestamp = timestamp;
    }

    public String getRootCause() {
        return rootCause;
    }

    public void setRootCause(String rootCause) {
        this.rootCause = rootCause;
    }

    public String getExplanation() {
        return explanation;
    }

    public void setExplanation(String explanation) {
        this.explanation = explanation;
    }

    public DiagnosisSeverity getSeverity() {
        return severity;
    }

    public void setSeverity(DiagnosisSeverity severity) {
        this.severity = severity;
    }

    public double getConfidenceScore() {
        return confidenceScore;
    }

    public void setConfidenceScore(double confidenceScore) {
        this.confidenceScore = confidenceScore;
    }

    public RecoveryStrategy getSuggestedRecoveryStrategy() {
        return suggestedRecoveryStrategy;
    }

    public void setSuggestedRecoveryStrategy(RecoveryStrategy suggestedRecoveryStrategy) {
        this.suggestedRecoveryStrategy = suggestedRecoveryStrategy;
    }

    public String getReasonForSuggestion() {
        return reasonForSuggestion;
    }

    public void setReasonForSuggestion(String reasonForSuggestion) {
        this.reasonForSuggestion = reasonForSuggestion;
    }

    public String getSource() {
        return source;
    }

    public void setSource(String source) {
        this.source = source;
    }

    public long getLatencyMillis() {
        return latencyMillis;
    }

    public void setLatencyMillis(long latencyMillis) {
        this.latencyMillis = latencyMillis;
    }

    public String getRawModelResponse() {
        return rawModelResponse;
    }

    public void setRawModelResponse(String rawModelResponse) {
        this.rawModelResponse = rawModelResponse;
    }
}
